"use server";

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet } from "./wallet";
import { SANDBOX } from "./sandbox";
import { addMonths } from "./billing-terms";
import { currentPromo, promoPriceCents } from "./promotions";
import { emailVerificationError } from "./email-verification";
import { encryptSecret, decryptSecret } from "./crypto-box";
import {
  isValidHostingDomain,
  normalizeHostingDomain,
  deriveUsername,
  isValidUnixUsername,
  isValidSubdomainLabel,
  isValidCronSchedule,
  isValidCronCommand,
  subdomainPaths,
  addonDomainPaths,
  planLimits,
  pointToRecords,
} from "./hosting";
import { hostingAppCatalog } from "../worker/hosting";
import { fsList, fsMkdir, fsDelete, fsTargetFor, type HostingFsTarget } from "./hosting-fs";

export type HostingResult = { ok?: boolean; error?: string; accountId?: string };

// The active-ish states that reserve a domain / occupy a node slot.
const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;

/** Least-loaded enabled+online node with account headroom. */
async function scheduleHostingNode(): Promise<{ id: string } | null> {
  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (!nodes.length) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => ({
      node: n,
      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
    })),
  );
  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
  return withRoom.length ? { id: withRoom[0].node.id } : null;
}

/** A free jailed username on the node, derived from the email + random salt. */
async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
  for (let i = 0; i < 8; i++) {
    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
    if (!isValidUnixUsername(name)) continue;
    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
    if (!taken) return name;
  }
  throw new Error("Could not allocate a username — try again.");
}

