221	/**
222	 * Customer "Check now / Go live" — flag an ACTIVE account for an immediate
223	 * serve-verification + SSL recheck. The worker's fast lane (~30s) picks up
224	 * recheckRequested accounts before their routine 10-min cadence, verifies HTTP/
225	 * HTTPS from the node, self-heals a stale cert vhost, and nudges the SSL sweep so a
226	 * trusted certificate can start issuing. Owner or admin; a no-op for non-active
227	 * accounts (nothing to verify until it's provisioned).
228	 */
229	export async function recheckHostingHealth(id: string): Promise<HostingResult> {
230	  const user = await requireUser();
231	  const a = await db.hostingAccount.findUnique({ where: { id }, select: { userId: true, status: true } });
232	  if (!a) return { error: "Not found." };
233	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
234	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
235	  await db.hostingAccount.update({ where: { id }, data: { recheckRequested: true } });
236	  revalidatePath(`/dashboard/hosting/${id}`);
237	  return { ok: true };
238	}
