246	  if (a.status !== "FAILED") return { error: "This account isn’t in a failed state." };
247	  await db.hostingAccount.update({ where: { id }, data: { status: "PENDING", error: null } });
248	  revalidatePath("/dashboard/hosting");
249	  return { ok: true };
250	}
