 *
 * These are NOT sold in the Business Email storefront. They exist so a hosting
 * customer's "N mailboxes included" promise can be honoured by handing them a
 * complimentary EmailSubscription (see lib/hosting-email.ts → setupHostingEmail),
 * which then reuses the exact same audited /dashboard/email flow (addMailbox,
 * DNS verification, Mailcow provisioning) as a paid subscription.
 *
 * They are kept OUT of the paid picker two ways, belt-and-braces:
 *   - `active: false`  — /dashboard/email storefront queries `where: { active: true }`,
 *                        and orderEmailHosting() rejects any plan that isn't active,
 *                        so a bundled plan can never be *bought* through the paid path.
 *   - `priceCents: 0`  — complimentary; no wallet charge is ever taken for these.
 *   - name suffix "(bundled)" — human marker in the admin plan list.
 *
 * Mailbox counts mirror the hosting Starter / Business / Pro `mailboxes` (1 / 10 / 25)
 * seeded by seed-hosting-plans.ts. setupHostingEmail matches a hosting account to its
 * bundled plan by (mailboxes === plan.mailboxes, priceCents 0, active false).
 *
 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-hosting-email-plans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type BundledSpec = {
  name: string;
  mailboxes: number; // must match the hosting plan's `mailboxes`
  storageGB: number; // per mailbox
  sortOrder: number;
};

// mailboxes 1 / 10 / 25 mirror hosting Starter / Business / Pro.
const BUNDLED: BundledSpec[] = [
  { name: "Starter Hosting Email (bundled)", mailboxes: 1, storageGB: 10, sortOrder: 90 },
  { name: "Business Hosting Email (bundled)", mailboxes: 10, storageGB: 10, sortOrder: 91 },
  { name: "Pro Hosting Email (bundled)", mailboxes: 25, storageGB: 10, sortOrder: 92 },
];

async function main() {
  let created = 0;
  let updated = 0;

  for (const spec of BUNDLED) {
    const data = {
      name: spec.name,
      mailboxes: spec.mailboxes,
      storageGB: spec.storageGB,
      priceCents: 0, // complimentary — never charged
      termMonths: 1,
      active: false, // kept OUT of the paid Business Email storefront
      sortOrder: spec.sortOrder,
    };

    // No DB unique constraint on name — dedupe manually (matches seed-email-plans.ts).
    const existing = await db.emailPlan.findFirst({ where: { name: spec.name } });
    if (existing) {
      await db.emailPlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.emailPlan.create({ data });
      created++;
    }
    console.log(
      `  ${spec.name.padEnd(34)} ${spec.mailboxes} mailbox(es) · ${spec.storageGB} GB each · FREE (bundled, hidden)`,
    );
  }

  const total = await db.emailPlan.count();
  console.log(`\nBundled EmailPlans seeded: ${created} created, ${updated} updated. Total EmailPlans in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

"use server";

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";

/**
 * BUNDLED HOSTING EMAIL
 *
 * Hosting plans advertise "1 / 10 / 25 mailboxes included", but nothing turned
 * that promise into something a customer could use. This module does the ONE
 * thing needed to bridge the gap: it mints a COMPLIMENTARY EmailSubscription for
 * a hosting account's primary domain, on the matching bundled EmailPlan, then
 * hands the customer straight to the existing, audited /dashboard/email UI to add
 * mailboxes and verify their domain.
 *
 * We deliberately write NO new provisioning / Mailcow / SSH code here. The real
 * mailbox creation happens through the already-audited addMailbox() path when the
 * customer adds a mailbox in /dashboard/email — which enforces the plan quota, the
 * external-domain DNS-verification gate, and Mailcow's per-address uniqueness.
 *
 * SECURITY — the 2026-07-25 cross-tenant email-takeover fix is preserved exactly:
 *   1. GLOBAL domain dedup: one EmailSubscription per domain across ALL users. We
 *      reuse the identical query subscribeEmail/orderEmailHosting uses. If another
 *      tenant already holds the domain we return the SAME "contact support" error
 *      and mint nothing — bundled email can never be created for a domain another
 *      tenant owns.
 *   2. The complimentary subscription is created external:true, verified:false —
 *      so even holding the subscription row grants no power over the domain's mail
 *      until the customer proves DNS control. addMailbox()/retryMailboxProvision()
 *      both refuse to touch Mailcow until then.
 */

export type HostingEmailResult = { ok?: boolean; error?: string; subscriptionId?: string };

/**
 * Find the bundled (free, hidden) EmailPlan whose included-mailbox count matches
 * the hosting plan's `mailboxes`. Bundled plans are seeded priceCents:0 +
 * active:false (see prisma/seed-hosting-email-plans.ts); we match on all three so
 * a paid tier that happens to share a mailbox count is never picked up.
 */
async function findBundledPlan(mailboxes: number) {
  return db.emailPlan.findFirst({
    where: { mailboxes, priceCents: 0, active: false },
    orderBy: { sortOrder: "asc" },
  });
}

/**
 * Status for the hosting Email tab: how many mailboxes the plan includes, and
 * whether the account's bundled email subscription already exists (so the UI can
 * either show "Set up my email" or link into /dashboard/email). Owner or admin.
 */
export async function getHostingEmailStatus(accountId: string): Promise<{
  error?: string;
  planName?: string;
  primaryDomain?: string;
  includedMailboxes?: number;
  hasSubscription?: boolean;
  subscriptionId?: string;
  verified?: boolean;
}> {
  const user = await requireUser();

  const account = await db.hostingAccount.findUnique({
    where: { id: accountId },
    include: { plan: { select: { name: true, mailboxes: true } } },
  });
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };

  // Existing subscription for this domain owned by the ACCOUNT OWNER (bundled or
  // paid — either way the owner already controls this domain's mail).
  const sub = await db.emailSubscription.findFirst({
    where: { domainName: account.primaryDomain, userId: account.userId, status: { not: "CANCELLED" } },
    select: { id: true, verified: true },
  });

  return {
    planName: account.plan.name,
    primaryDomain: account.primaryDomain,
    includedMailboxes: account.plan.mailboxes,
    hasSubscription: !!sub,
    subscriptionId: sub?.id,
    verified: sub?.verified ?? false,
  };
}

/**
 * Turn on the bundled email that ships with a hosting account: create a
 * complimentary EmailSubscription for the account's primary domain on the
 * matching bundled EmailPlan. Owner or admin; blocked while impersonating (a
 * complimentary grant is still a mutation made in the customer's name).
 *
 * Idempotent: if the owner already has a subscription for this domain, no-op.
 * No wallet charge is ever taken. No mailboxes are provisioned here — the
 * customer adds them via the existing /dashboard/email flow.
 */
export async function setupHostingEmail(accountId: string): Promise<HostingEmailResult> {
  const user = await requireUser();
  // A complimentary grant is a mutation attributed to the customer — support must
  // not perform it while impersonating, consistent with every other write path.
  await assertNotImpersonating();

  const account = await db.hostingAccount.findUnique({
    where: { id: accountId },
    include: { plan: { select: { name: true, mailboxes: true } } },
  });
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };

  const domain = account.primaryDomain;

  // GLOBAL domain dedup — the exact guard subscribeEmail/orderEmailHosting use.
  // One subscription per domain across ALL users (2026-07-25 cross-tenant takeover
  // fix). If another tenant holds it, mint NOTHING and return the same support
  // message; if the owner already holds it (bundled or paid), this is an
  // idempotent no-op.
  const dupe = await db.emailSubscription.findFirst({
    where: { domainName: domain, status: { not: "CANCELLED" } },
  });
  if (dupe) {
    if (dupe.userId === account.userId) {
      // Already set up for the account owner — idempotent success.
      return { ok: true, subscriptionId: dupe.id };
    }
    return {
      error:
        "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
    };
  }

  const plan = await findBundledPlan(account.plan.mailboxes);
  if (!plan) {
    return {
      error:
        "Bundled email isn't configured for this plan yet. Please contact support — no charge, we'll switch it on.",
    };
  }

  // Complimentary subscription. EXTERNAL + UNVERIFIED on purpose: holding the row
  // grants no power over the domain's mail until the customer proves DNS control
  // in /dashboard/email, which is where addMailbox() enforces the gate. autoRenew
  // is tied to the hosting account (it renews as long as the hosting lives);
  // expiry tracks the account so it doesn't outlive it.
  const sub = await db.emailSubscription.create({
    data: {
      userId: account.userId,
      domainName: domain,
      emailPlanId: plan.id,
      status: "ACTIVE",
      autoRenew: true,
      expiresAt: account.expiresAt,
      external: true,
      verified: false,
      verifiedAt: null,
      verifyToken: randomBytes(24).toString("hex"),
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: account.userId,
        action: "hostingemail.setup",
        detail: `${domain} · bundled ${plan.name} (${plan.mailboxes} mailbox${plan.mailboxes === 1 ? "" : "es"}) via hosting ${account.plan.name}`,
      },
    })
    .catch(() => {});

  revalidatePath(`/dashboard/hosting/${accountId}`);
  revalidatePath("/dashboard/email");
  return { ok: true, subscriptionId: sub.id };
}

